  1	//! Port of `lib/Platinenmacher/parser/command.{c,h}` — the serial/console
  2	//! command parser.
  3	//!
  4	//! The C version is a character-at-a-time state machine over two global heap
  5	//! buffers, with a fixed table of `command_t` structs holding a
  6	//! `void (*function_cb)(struct command *)`. Registered handlers are things
  7	//! like `render_cmd_cb()` in `src/esp32/gui.c`.
  8	//!
  9	//! What the port keeps:
 10	//!
 11	//! * The state machine, byte for byte: `\r` dispatches, the first space inside
 12	//!   a command switches to argument collection, later spaces are part of the
 13	//!   arguments, a leading space in [`State::Idle`] is skipped.
 14	//! * Unknown commands dispatch to entry 0, the "unknown command" slot that
 15	//!   `command_init()` registers before anything else.
 16	//! * `CMD_MAX` caps the table *including* that unknown slot, so only
 17	//!   [`CMD_MAX`] − 1 real commands fit. Registering past it fails with
 18	//!   [`Error::OutOfBounds`], as `command_register()` does.
 19	//! * The command name is capped at [`CMD_LENGTH`] and the arguments at
 20	//!   [`CMD_ARGS_LENGTH`].
 21	//!
 22	//! What the port deliberately changes:
 23	//!
 24	//! * **No echo.** `command_parser()` calls `putchar()` on every byte it
 25	//!   consumes. Console I/O (and the `save_printf` semaphore that guards it)
 26	//!   belongs to the firmware serial task, not to a parser — see the crate
 27	//!   docs. [`CommandParser::parse`] is pure.
 28	//! * **No overflow.** The C parser writes past the end of its `CMD_LENGTH + 1`
 29	//!   and `CMD_ARGS_LENGTH + 1` buffers when a line is longer, corrupting the
 30	//!   heap. Here the excess characters are dropped. An over-long name therefore
 31	//!   arrives truncated and matches nothing, dispatching to the unknown handler.
 32	//! * **No `strcmp(NULL, ..)`.** In C the unknown entry is a zeroed global, so
 33	//!   `find_command()` compares against a `NULL` name on every lookup, which is
 34	//!   undefined behaviour. Here the unknown entry simply has no name and never
 35	//!   participates in matching.
 36	//! * The handler receives the command name **as typed**, not the name stored
 37	//!   in the table. For a matched command those are the same string; for an
 38	//!   unknown command C passed a `NULL` name, and the typed text is strictly
 39	//!   more useful.
 40	//!
 41	//! A quirk that is *preserved* because callers depend on `\r` framing: `\n` is
 42	//! not a terminator, it is an ordinary character. Feeding `"cmd\r\n"` leaves
 43	//! the `\n` as the first character of the *next* command. The firmware feeds
 44	//! `\r`-terminated console lines, so this only bites on CRLF input.
 45	//!
 46	//! ```
 47	//! use pm_parser::{CommandParser, Invocation};
 48	//! use std::cell::Cell;
 49	//!
 50	//! let hits = Cell::new(0);
 51	//! let mut parser = CommandParser::new();
 52	//! parser
 53	//!     .register("render", |_: &Invocation<'_>| hits.set(hits.get() + 1))
 54	//!     .unwrap();
 55	//! parser.parse("render\r");
 56	//! assert_eq!(hits.get(), 1);
 57	//! ```
 58	
 59	use crate::error::Error;
 60	
 61	/// `CMD_MAX` from `command.h`: table size, unknown-command slot included.
 62	pub const CMD_MAX: usize = 10;
 63	/// `CMD_LENGTH` from `command.h`: longest command name that can be parsed.
 64	pub const CMD_LENGTH: usize = 10;
 65	/// `CMD_ARGS_LENGTH` from `command.h`: longest argument string.
 66	pub const CMD_ARGS_LENGTH: usize = 70;
 67	
 68	/// Port of `cmd_t`.
 69	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
 70	pub enum State {
 71	    /// `CMD_IDLE`: skipping leading spaces.
 72	    Idle,
 73	    /// `CMD_COMMAND`: collecting the command name.
 74	    Command,
 75	    /// `CMD_ARGS`: collecting the argument string.
 76	    Args,
 77	}
 78	
 79	/// What a handler is given when its command fires.
 80	///
 81	/// Replaces the `command_t *` that C handed to `function_cb`.
 82	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
 83	pub struct Invocation<'a> {
 84	    /// The command name as typed (already truncated to [`CMD_LENGTH`]).
 85	    pub command: &'a str,
 86	    /// Everything after the first space, truncated to [`CMD_ARGS_LENGTH`].
 87	    /// Empty when the command was given without arguments.
 88	    pub args: &'a str,
 89	}
 90	
 91	/// Typed replacement for `void (*function_cb)(struct command *cmd)`.
 92	///
 93	/// Implemented for every `FnMut(&Invocation<'_>)`, so plain closures work.
 94	pub trait CommandHandler {
 95	    /// Run the command.
 96	    fn call(&mut self, invocation: &Invocation<'_>);
 97	}
 98	
 99	impl<F> CommandHandler for F
100	where
101	    F: FnMut(&Invocation<'_>),
102	{
103	    fn call(&mut self, invocation: &Invocation<'_>) {
104	        self(invocation)
105	    }
106	}
107	
108	struct Entry<'a> {
109	    /// `None` for the unknown-command slot, which never matches.
110	    name: Option<String>,
111	    handler: Box<dyn CommandHandler + 'a>,
112	}
113	
114	/// The command table plus the parser state machine.
115	///
116	/// Replaces the file-scope globals of `command.c` (`cmd_list`, `max_cmd`,
117	/// `state`, `cmd_buf`, `args_buf`), so several parsers can coexist and tests
118	/// do not share state.
119	pub struct CommandParser<'a> {
120	    /// Entry 0 is always the unknown-command slot, as after `command_init()`.
121	    entries: Vec<Entry<'a>>,
122	    state: State,
123	    cmd: String,
124	    args: String,
125	}
126	
127	impl Default for CommandParser<'_> {
128	    fn default() -> Self {
129	        Self::new()
130	    }
131	}
132	
133	impl<'a> CommandParser<'a> {
134	    /// Port of `command_init()`: empty buffers, state `CMD_COMMAND`, and the
135	    /// unknown-command slot registered as entry 0.
136	    ///
137	    /// The unknown handler does nothing, matching C's zeroed `unknown_cmd`
138	    /// whose `function_cb` is `NULL`. Use [`CommandParser::set_unknown_handler`]
139	    /// to give it behaviour.
140	    pub fn new() -> Self {
141	        Self {
142	            entries: vec![Entry {
143	                name: None,
144	                handler: Box::new(|_: &Invocation<'_>| {}),
145	            }],
146	            // command_init() leaves the machine in CMD_COMMAND, so State::Idle
147	            // is only reachable by an explicit reset; it is kept for fidelity.
148	            state: State::Command,
149	            cmd: String::with_capacity(CMD_LENGTH),
150	            args: String::with_capacity(CMD_ARGS_LENGTH),
151	        }
152	    }
153	
154	    /// Replace the handler for unrecognised commands (entry 0).
155	    pub fn set_unknown_handler(&mut self, handler: impl CommandHandler + 'a) {
156	        self.entries[0].handler = Box::new(handler);
157	    }
158	
159	    /// Port of `command_register()`.
160	    ///
161	    /// Fails with [`Error::OutOfBounds`] once the table holds [`CMD_MAX`]
162	    /// entries — the unknown-command slot counts, exactly as `max_cmd` does
163	    /// in C.
164	    ///
165	    /// Duplicate names are accepted and the first registration wins, because
166	    /// `find_command()` returns the first match. A name longer than
167	    /// [`CMD_LENGTH`] is accepted too, and can never match, because the parser
168	    /// truncates what it reads — both are C behaviour.
169	    pub fn register(
170	        &mut self,
171	        name: &str,
172	        handler: impl CommandHandler + 'a,
173	    ) -> Result<(), Error> {
174	        if self.entries.len() >= CMD_MAX {
175	            return Err(Error::OutOfBounds);
176	        }
177	        self.entries.push(Entry {
178	            name: Some(name.to_owned()),
179	            handler: Box::new(handler),
180	        });
181	        Ok(())
182	    }
183	
184	    /// Number of registered commands, the unknown-command slot excluded.
185	    pub fn len(&self) -> usize {
186	        self.entries.len() - 1
187	    }
188	
189	    /// `true` when no command beyond the unknown-command slot is registered.
190	    pub fn is_empty(&self) -> bool {
191	        self.len() == 0
192	    }
193	
194	    /// Current state machine position.
195	    pub fn state(&self) -> State {
196	        self.state
197	    }
198	
199	    /// Port of `command_parser(char *buf, uint32_t len)`, minus the echo.
200	    pub fn parse(&mut self, input: &str) {
201	        for c in input.chars() {
202	            self.parse_char(c);
203	        }
204	    }
205	
206	    /// Port of `command_parse_char()`.
207	    pub fn parse_char(&mut self, c: char) {
208	        if c == '\r' {
209	            // C sets state before dispatching, so the next line starts in
210	            // CMD_COMMAND even if this one ended mid-arguments.
211	            self.state = State::Command;
212	            self.dispatch();
213	            return;
214	        }
215	
216	        match self.state {
217	            State::Idle => {
218	                if c == ' ' {
219	                    return;
220	                }
221	                // C falls through from CMD_IDLE into CMD_COMMAND: the
222	                // character that ended the idle run is part of the command.
223	                self.state = State::Command;
224	                self.push_cmd(c);
225	            }
226	            State::Command => {
227	                if c == ' ' {
228	                    self.state = State::Args;
229	                } else {
230	                    self.push_cmd(c);
231	                }
232	            }
233	            // Everything after the first space is arguments, spaces included.
234	            State::Args => self.push_args(c),
235	        }
236	    }
237	
238	    /// Drop the half-parsed line and return to the post-`command_init()` state.
239	    pub fn reset(&mut self) {
240	        self.state = State::Command;
241	        self.cmd.clear();
242	        self.args.clear();
243	    }
244	
245	    /// Port of `find_command()` + `run_command()`.
246	    fn dispatch(&mut self) {
247	        // C: `find_command()` returns 0 — the unknown slot — when nothing
248	        // matches, and the unknown slot itself has no name to match against.
249	        let idx = self
250	            .entries
251	            .iter()
252	            .position(|e| e.name.as_deref() == Some(self.cmd.as_str()))
253	            .unwrap_or(0);
254	
255	        let invocation = Invocation {
256	            command: self.cmd.as_str(),
257	            args: self.args.as_str(),
258	        };
259	        // Disjoint field borrows: the handler is borrowed mutably out of
260	        // `entries` while the buffers are borrowed immutably.
261	        self.entries[idx].handler.call(&invocation);
262	
263	        // C: run_command() zeroes both buffers afterwards.
264	        self.cmd.clear();
265	        self.args.clear();
266	    }
267	
268	    fn push_cmd(&mut self, c: char) {
269	        // C overflows the buffer here; we drop the excess instead.
270	        if self.cmd.chars().count() < CMD_LENGTH {
271	            self.cmd.push(c);
272	        }
273	    }
274	
275	    fn push_args(&mut self, c: char) {
276	        if self.args.chars().count() < CMD_ARGS_LENGTH {
277	            self.args.push(c);
278	        }
279	    }
280	}
