287	    /// Records every dispatch as `(command, args)` so tests can assert on the
288	    /// exact strings the C callbacks would have seen.
289	    #[derive(Default)]
290	    struct Log(RefCell<Vec<(String, String)>>);
291	
292	    impl Log {
293	        fn record(&self, i: &Invocation<'_>) {
294	            self.0
295	                .borrow_mut()
296	                .push((i.command.to_owned(), i.args.to_owned()));
297	        }
298	        fn take(&self) -> Vec<(String, String)> {
299	            self.0.borrow_mut().drain(..).collect()
300	        }
301	    }
302	
303	    #[test]
304	    fn dispatches_two_registered_commands() {
305	        let render = Log::default();
306	        let reboot = Log::default();
307	        let mut parser = CommandParser::new();
308	        parser.register("render", |i: &Invocation<'_>| render.record(i)).unwrap();
309	        parser.register("reboot", |i: &Invocation<'_>| reboot.record(i)).unwrap();
310	
311	        parser.parse("render\rreboot now\r");
312	
313	        assert_eq!(render.take(), vec![("render".to_string(), String::new())]);
314	        assert_eq!(reboot.take(), vec![("reboot".to_string(), "now".to_string())]);
315	    }
316	
317	    #[test]
318	    fn unknown_command_falls_back_to_entry_zero() {
319	        let known = Log::default();
320	        let unknown = Log::default();
321	        let mut parser = CommandParser::new();
322	        parser.set_unknown_handler(|i: &Invocation<'_>| unknown.record(i));
323	        parser.register("render", |i: &Invocation<'_>| known.record(i)).unwrap();
324	
325	        parser.parse("nope arg\r");
326	
327	        assert!(known.take().is_empty());
328	        assert_eq!(unknown.take(), vec![("nope".to_string(), "arg".to_string())]);
329	    }
330	
331	    #[test]
332	    fn empty_line_dispatches_the_unknown_handler() {
333	        // C: find_command("") matches nothing, so entry 0 runs with empty args.
334	        let unknown = Log::default();
335	        let mut parser = CommandParser::new();
336	        parser.set_unknown_handler(|i: &Invocation<'_>| unknown.record(i));
337	
338	        parser.parse("\r");
339	
340	        assert_eq!(unknown.take(), vec![(String::new(), String::new())]);
341	    }
342	
343	    #[test]
344	    fn default_unknown_handler_is_a_noop() {
345	        // C's unknown_cmd has a NULL function_cb; run_command() skips the call.
346	        let mut parser = CommandParser::new();
347	        parser.parse("whatever\r");
348	        assert_eq!(parser.state(), State::Command);
349	    }
350	
351	    #[test]
352	    fn arguments_keep_every_space_after_the_first() {
353	        let log = Log::default();
354	        let mut parser = CommandParser::new();
355	        parser.register("set", |i: &Invocation<'_>| log.record(i)).unwrap();
356	
357	        parser.parse("set  a b \r");
358	
359	        // The first space switches to CMD_ARGS and is swallowed; the rest are
360	        // copied verbatim.
361	        assert_eq!(log.take(), vec![("set".to_string(), " a b ".to_string())]);
362	    }
363	
364	    #[test]
365	    fn buffers_are_cleared_between_commands() {
366	        let log = Log::default();
367	        let mut parser = CommandParser::new();
368	        parser.register("set", |i: &Invocation<'_>| log.record(i)).unwrap();
369	
370	        parser.parse("set value\rset\r");
371	
372	        assert_eq!(
373	            log.take(),
374	            vec![
375	                ("set".to_string(), "value".to_string()),
376	                ("set".to_string(), String::new()),
377	            ]
378	        );
379	    }
