381	    #[test]
382	    fn over_long_command_is_truncated_and_unknown() {
383	        let known = Log::default();
384	        let unknown = Log::default();
385	        let mut parser = CommandParser::new();
386	        parser.set_unknown_handler(|i: &Invocation<'_>| unknown.record(i));
387	        parser
388	            .register("0123456789abc", |i: &Invocation<'_>| known.record(i))
389	            .unwrap();
390	
391	        parser.parse("0123456789abc\r");
392	
393	        // CMD_LENGTH characters survive; the registered 13-char name is
394	        // unreachable, exactly as in C (where the tail smashed the heap).
395	        assert!(known.take().is_empty());
396	        assert_eq!(unknown.take(), vec![("0123456789".to_string(), String::new())]);
397	    }
