399	    #[test]
400	    fn over_long_arguments_are_truncated() {
401	        let log = Log::default();
402	        let mut parser = CommandParser::new();
403	        parser.register("x", |i: &Invocation<'_>| log.record(i)).unwrap();
404	
405	        let long = "a".repeat(CMD_ARGS_LENGTH + 20);
406	        parser.parse(&format!("x {long}\r"));
407	
408	        let recorded = log.take();
409	        assert_eq!(recorded.len(), 1);
410	        assert_eq!(recorded[0].1.len(), CMD_ARGS_LENGTH);
411	    }
