414	    fn registration_is_capped_at_cmd_max_including_the_unknown_slot() {
415	        let mut parser = CommandParser::new();
416	        for i in 0..CMD_MAX - 1 {
417	            parser
418	                .register(&format!("c{i}"), |_: &Invocation<'_>| {})
419	                .unwrap();
420	        }
421	        assert_eq!(parser.len(), CMD_MAX - 1);
422	        assert_eq!(
423	            parser.register("one_more", |_: &Invocation<'_>| {}),
424	            Err(Error::OutOfBounds)
425	        );
426	    }
