429	    fn first_registration_of_a_duplicate_name_wins() {
430	        let first = Log::default();
431	        let second = Log::default();
432	        let mut parser = CommandParser::new();
433	        parser.register("dup", |i: &Invocation<'_>| first.record(i)).unwrap();
434	        parser.register("dup", |i: &Invocation<'_>| second.record(i)).unwrap();
