442	    #[test]
443	    fn newline_is_an_ordinary_character() {
444	        // Faithful to C: only '\r' dispatches, so CRLF leaves the '\n' at the
445	        // head of the next command.
446	        let log = Log::default();
447	        let unknown = Log::default();
448	        let mut parser = CommandParser::new();
449	        parser.set_unknown_handler(|i: &Invocation<'_>| unknown.record(i));
450	        parser.register("render", |i: &Invocation<'_>| log.record(i)).unwrap();
451	
452	        parser.parse("render\r\nrender\r");
453	
454	        assert_eq!(log.take().len(), 1);
455	        assert_eq!(unknown.take(), vec![("\nrender".to_string(), String::new())]);
