459	    fn idle_state_skips_leading_spaces() {
460	        let log = Log::default();
461	        let mut parser = CommandParser::new();
462	        parser.register("render", |i: &Invocation<'_>| log.record(i)).unwrap();
463	
464	        parser.reset_to_idle_for_test();
