470	    #[test]
471	    fn command_state_does_not_skip_leading_spaces() {
472	        // In CMD_COMMAND the first space switches to CMD_ARGS even if no
473	        // command characters were seen yet: " render" is an empty command with
474	        // "render" as its arguments.
475	        let unknown = Log::default();
476	        let mut parser = CommandParser::new();
477	        parser.set_unknown_handler(|i: &Invocation<'_>| unknown.record(i));
478	
479	        parser.parse(" render\r");
480	
481	        assert_eq!(unknown.take(), vec![(String::new(), "render".to_string())]);
482	    }
483	
484	    #[test]
485	    fn reset_drops_a_half_parsed_line() {
486	        let log = Log::default();
487	        let mut parser = CommandParser::new();
488	        parser.register("render", |i: &Invocation<'_>| log.record(i)).unwrap();
489	
490	        parser.parse("ren");
491	        parser.reset();
492	        parser.parse("render\r");
493	
494	        assert_eq!(log.take(), vec![("render".to_string(), String::new())]);
495	    }
