497	    impl CommandParser<'_> {
498	        /// `State::Idle` is unreachable through the public API because
499	        /// `command_init()` starts in `CMD_COMMAND`; this puts the machine
500	        /// there so the idle branch stays covered.
501	        fn reset_to_idle_for_test(&mut self) {
502	            self.reset();
503	            self.state = State::Idle;
504	        }
505	    }
