     1	//! Port of `lib/helper/printfb.c` — dump a framebuffer as decimal numbers.
     2	//!
     3	//! The C `printf_fb()` walks the buffer and `printf()`s it straight to the
     4	//! console. This port only *formats*: it returns a `String`, or writes into
     5	//! any [`core::fmt::Write`] sink.
     6	//!
     7	//! That split is deliberate. The firmware never prints without holding the
     8	//! print semaphore behind the `save_sprintf` / `save_snprintf` macros in
     9	//! `include/tasks.h`; those macros are FreeRTOS concurrency plumbing and stay
    10	//! in the firmware crate. Keeping the formatting pure means the firmware wraps
    11	//! the semaphore around a value this crate produced, and the host tests can
    12	//! assert on the exact text without capturing stdout.
    13	//!
    14	//! Layout is byte-identical to the C output: one row per `width` index, each
    15	//! value followed by a comma (so every line ends in a trailing comma) and the
    16	//! row terminated by `\n`. Note that C indexes `fb[height * i + j]`, i.e. the
    17	//! outer loop strides by `height` — kept as-is.
    18	
    19	use core::fmt::Write;
    20	
    21	use crate::error::Error;
    22	
    23	/// Format `fb` the way `printf_fb()` prints it.
    24	///
    25	/// Returns [`Error::OutOfBounds`] when `fb` is smaller than `width * height`,
    26	/// or when that product overflows. The C version reads past the end of the
    27	/// buffer instead.
    28	pub fn format_fb(fb: &[u8], width: usize, height: usize) -> Result<String, Error> {
    29	    let mut out = String::new();
    30	    write_fb(&mut out, fb, width, height)?;
    31	    Ok(out)
    32	}
    33	
    34	/// [`format_fb`] into a caller-supplied sink.
    35	///
    36	/// Returns [`Error::OutOfBounds`] on a short buffer and [`Error::Fail`] if the
    37	/// sink itself fails.
    38	pub fn write_fb<W: Write>(
    39	    out: &mut W,
    40	    fb: &[u8],
    41	    width: usize,
    42	    height: usize,
    43	) -> Result<(), Error> {
    44	    let needed = width.checked_mul(height).ok_or(Error::OutOfBounds)?;
    45	    if fb.len() < needed {
    46	        return Err(Error::OutOfBounds);
    47	    }
    48	
    49	    for i in 0..width {
    50	        for j in 0..height {
    51	            write!(out, "{},", fb[height * i + j]).map_err(|_| Error::Fail)?;
    52	        }
