  2	//!
  3	//! Used by the firmware to walk the text files read off the SD card:
  4	//! `src/esp32/wifi.c` (SSID on line 1, password on line 2), `src/esp32/gps.c`
  5	//! (`TIMEZONE`), `src/esp32/map_loader.c` (waypoint/OTA files) and
  6	//! `src/esp32/ota.c`.
  7	//!
  8	//! The C functions take a `char *source` cursor and return the cursor for the
  9	//! next line, or `NULL` once the source is exhausted. The port keeps that
 10	//! shape — `Option<&str>` in, `Option<&str>` out — so call sites translate
 11	//! line for line, and so the quirks the firmware depends on stay observable:
 12	//!
 13	//! * `\r` is **skipped, not treated as a terminator**. `"a\rb"` is one line
 14	//!   `"ab"`. Only `\n` ends a line.
 15	//! * A source with no `\n` left yields the remaining text *and* a `None`
 16	//!   cursor, so the last line of a file without a trailing newline is still
 17	//!   returned — but the caller cannot distinguish "last line" from "empty" by
 18	//!   the cursor alone; it must look at the destination, exactly as the C
 19	//!   callers do.
 20	//! * `readline(None, ..)` leaves the destination untouched (C returns before
 21	//!   writing the terminator); `readline(Some(""), ..)` clears it.
 22	//!
 23	//! Where C wrote into a caller-supplied `char *destination` with no bounds
 24	//! check, this port appends into a `&mut String`, which cannot overflow. That
 25	//! is the one intentional deviation.
 26	
 27	/// Read one line out of `source` into `destination`.
 28	///
 29	/// Returns the cursor for the next line, or `None` when `source` was `NULL`
 30	/// (`None`) or held no further `\n`.
 31	///
 32	/// `destination` is cleared first, then filled with the line's bytes minus any
 33	/// `\r`. Mirrors `char *readline(char *source, char *destination)`.
 34	pub fn readline<'a>(source: Option<&'a str>, destination: &mut String) -> Option<&'a str> {
 35	    // C: `if (source == 0) return 0;` — destination is not touched.
 36	    let source = source?;
 37	
 38	    destination.clear();
 39	
 40	    let bytes = source.as_bytes();
 41	    // Start of the current run of bytes to copy. `\r` and `\n` are ASCII, so
 42	    // slicing at those offsets never splits a UTF-8 sequence.
 43	    let mut start = 0;
 44	    for (i, &b) in bytes.iter().enumerate() {
 45	        match b {
 46	            b'\n' => {
 47	                destination.push_str(&source[start..i]);
 48	                // C: `break` then `return ++source` — the cursor points just
 49	                // past the newline, which may be the empty remainder.
 50	                return Some(&source[i + 1..]);
 51	            }
 52	            b'\r' => {
 53	                destination.push_str(&source[start..i]);
 54	                start = i + 1;
 55	            }
 56	            _ => {}
 57	        }
 58	    }
 59	
 60	    // C: `if (*source == 0) { *destination = 0; return 0; }` — the trailing
 61	    // partial line is still handed to the caller, the cursor is NULL.
 62	    destination.push_str(&source[start..]);
 63	    None
 64	}
