 66	/// Length of the first line of `source`, *including* room for the terminating
 67	/// NUL, or `0` when there is no `\n` in `source`.
 68	///
 69	/// Mirrors `size_t countline(char *source)`, quirks included:
 70	///
 71	/// * `\r` bytes are not counted.
 72	/// * A source without a `\n` returns `0`, **not** the length of the text. The
 73	///   C caller `src/esp32/ota.c:101` feeds the result straight to
 74	///   `RTOS_Malloc()`, so a URL file without a trailing newline allocates
 75	///   nothing there. Preserved on purpose; fixing it is a firmware change, not
 76	///   a porting change.
 77	///
 78	/// The count is in bytes, as in C, because the C callers use it as an
 79	/// allocation size.
 80	pub fn countline(source: Option<&str>) -> usize {
 81	    let source = match source {
 82	        Some(s) => s,
 83	        None => return 0,
 84	    };
 85	
 86	    let mut count = 0;
 87	    for &b in source.as_bytes() {
 88	        if b == b'\n' {
 89	            // C: `break` then `return ++count;`
 90	            return count + 1;
 91	        }
 92	        if b == b'\r' {
 93	            continue;
 94	        }
 95	        count += 1;
 96	    }
 97	    0
 98	}
